{
  "assessment": "The source packet is a single LaTeX manuscript (draft.tex) describing time-domain evolutions of the nonlinear scalar ergoregion instability on a spinning boson star background. The extraction focuses on the weakly turbulent direct cascade that saturates the instability, comparing potential-type (kappa) and derivative (alpha) self-interactions. The key quantitative cluster is the nonlinear energy transfer timescales tau_NL_l for both interaction types, compared to linear e-folding timescales tau_EI_m. The source provides explicit values for the linear e-folding time of the m=1 mode (1.2e4 M), the monopole decay rate (-4e-3/M), and the nonlinear transfer timescales are shown in Fig. 3 but not numerically tabulated in the text. The source states that tau_pNL increases with ell (slowing cascade) and tau_dNL is roughly constant (efficient cascade), but no numeric values are given for these timescales. Therefore, the extraction captures the qualitative and semi-quantitative relations, with the linear e-folding time as a numeric fixed condition. The case is not authoring-ready because no numeric control-to-readout relation can be compiled for the nonlinear timescales; the only numeric control is the mode number ell, but the readout tau_NL lacks numeric values. The source also provides the energy spectrum relation E_ll ~ tau_NL_l under stationarity, but again without numeric coefficients. The extraction records the mechanisms, fixed conditions, and claims with appropriate uncertainty and statistical provenance.",
  "case_authoring_ready": false,
  "source": {
    "citation": "Nils Siemonsen, Weakly Turbulent Saturation of the Nonlinear Scalar Ergoregion Instability, Physical Review Letters (2026), DOI:10.1103/ytqg-v1j8",
    "journal_doi": "10.1103/ytqg-v1j8",
    "arxiv_versioned_id": "2510.07467v2"
  },
  "paper_scope": "The paper studies the nonlinear saturation of the ergoregion instability for a massless scalar field with potential-type (kappa) and derivative (alpha) self-interactions on a horizonless spinning boson star background. It focuses on the weakly turbulent direct cascade that transfers energy from low-ell modes to high-ell modes localized on the stable light ring, and compares nonlinear energy transfer timescales to linear e-folding timescales.",
  "mechanisms": [
    {
      "mechanism_id": "ergoregion_instability_linear",
      "statement": "Linear ergoregion instability of the ell=m=1 mode with energy e-folding time tau_EI_1 = 1.2e4 M, and growth timescales for higher modes increasing as tau_EI_m ~ exp(a m) in the eikonal limit.",
      "equations": [
        "tau_EI_m = [2 Im(omega_m)]^{-1} ~ e^{a m}, a>0 (eikonal limit)",
        "tau_EI_1 = 1.2e4 M"
      ],
      "variable_names": ["tau_EI_m", "omega_m", "m", "a"],
      "parameters": [
        {
          "name": "tau_EI_1_value",
          "value": 12000.0,
          "uncertainty": "source_unspecified",
          "unit": "M",
          "role": "Energy e-folding time of the ell=m=1 mode",
          "anchors": [
            {"line_start": 101, "line_end": 101, "support": "The energy's e-folding time is tau_EI_{m=1}=1.2e4 M."}
          ]
        }
      ],
      "anchors": [
        {"line_start": 72, "line_end": 72, "support": "Growth timescales of energy of unstable modes increase as tau_EI_m = [2 Im(omega_m)]^{-1} ~ e^{a m} with a>0 in the eikonal limit."},
        {"line_start": 101, "line_end": 101, "support": "On this background, the energy's e-folding time is tau_EI_{m=1}=1.2e4 M."}
      ]
    },
    {
      "mechanism_id": "turbulent_direct_cascade",
      "statement": "Weakly turbulent direct cascade transfers energy from low-ell modes to high-ell modes, with nonlinear transfer timescales tau_NL_l defined as the time between peaks of -<E_l> and -<E_{l+1}>. Potential-type interactions give a slowing cascade (tau_pNL increases with ell), while derivative interactions give an efficient cascade with roughly constant tau_dNL.",
      "equations": [
        "tau_NL_l = time between peak of -<E_l> and -<E_{l+1}>",
        "tau_pNL_l increases with ell (slowing cascade)",
        "tau_dNL_l ~ const (efficient cascade)"
      ],
      "variable_names": ["tau_NL_l", "tau_pNL_l", "tau_dNL_l", "E_l"],
      "parameters": [],
      "anchors": [
        {"line_start": 127, "line_end": 127, "support": "Define nonlinear timescale tau_NL_l as coordinate time between peak of -<E_l> and -<E_{l+1}>; potential-type lead to slowing direct cascade, derivative self-interactions induce efficient energy transfer with roughly constant nonlinear transfer time."}
      ]
    },
    {
      "mechanism_id": "parametric_driving_monopole",
      "statement": "The monopolar ell=m=0 mode drives parametric amplification of higher azimuthal modes; its decay rate is about -4e-3/M, roughly one order of magnitude larger than the growth rates of ergoregion unstable modes.",
      "equations": [
        "decay rate of E_00 ~ -4e-3/M"
      ],
      "variable_names": ["E_00", "decay_rate"],
      "parameters": [
        {
          "name": "monopole_decay_rate",
          "value": -0.004,
          "uncertainty": "source_unspecified",
          "unit": "1/M",
          "role": "Energy decay rate of the ell=m=0 mode",
          "anchors": [
            {"line_start": 111, "line_end": 111, "support": "We find the energy decay rate of this monopolar mode to be approx -4e-3/M."}
          ]
        }
      ],
      "anchors": [
        {"line_start": 111, "line_end": 111, "support": "Amplification may be triggered through parametric driving of growing ell=m>=2 modes by pumping energy into decaying ell=m=0 mode; decay rate approx -4e-3/M."},
        {"line_start": 268, "line_end": 268, "support": "Monopolar mode is pivotal for driving amplification; decay rate roughly one order of magnitude larger than growth rate of ergoregion unstable modes."}
      ]
    }
  ],
  "fixed_conditions": [
    {
      "condition_id": "boson_star_background",
      "statement": "Spinning boson star with internal frequency tilde_omega/mu=0.427, total mass mu M=3.85, total angular momentum J/M^2=1.013, compactness M/R=0.46, solitonic model coupling sigma=0.2, azimuthal index tilde_m=3.",
      "anchors": [
        {"line_start": 297, "line_end": 297, "support": "Boson star has internal frequency tilde_omega/mu=0.427, total mass mu M=3.85, total angular momentum J/M^2=1.013, compactness M/R=0.46."}
      ]
    },
    {
      "condition_id": "two_mode_initial_data",
      "statement": "Two-mode initial data with phi_11 and phi_22 set to linear ergoregion unstable states, amplitude ratio A_22/A_11 <= 1e-2, and A_11^2 << 1/(kappa M^2) and A_11^2 << 1/alpha.",
      "anchors": [
        {"line_start": 101, "line_end": 101, "support": "Two-mode small initial data: both phi_11 and phi_22 set to linear ergoregion unstable states with amplitude ratio A_22/A_11 <= 1e-2; amplitude set deep in linear regime."}
      ]
    },
    {
      "condition_id": "mode_truncation_ellmax_23",
      "statement": "Include only modes with ell=m>=0 up to ell_max=23, dissipate energy injected into the (ell_max+1)-th mode.",
      "anchors": [
        {"line_start": 101, "line_end": 101, "support": "Throughout the main text, we include only modes with ell=m>=0 up to ell_max=23 and dissipate energy injected into the (ell_max+1)-th mode."}
      ]
    },
    {
      "condition_id": "potential_type_only",
      "statement": "For potential-type self-interactions, alpha=0 and kappa>0.",
      "anchors": [
        {"line_start": 99, "line_end": 99, "support": "Throughout, the focus lies on alpha,kappa>0 unless stated otherwise."},
        {"line_start": 256, "line_end": 256, "support": "Focus lies on potential-type self-interactions and mode couplings induced by kappa>0, while assuming alpha=0."}
      ]
    },
    {
      "condition_id": "derivative_type_only",
      "statement": "For derivative self-interactions, kappa=0 and alpha>0.",
      "anchors": [
        {"line_start": 286, "line_end": 286, "support": "Pure scalar derivative self-interactions: alpha>0 and kappa=0."}
      ]
    }
  ],
  "controls": [
    {
      "name": "ell",
      "definition": "Azimuthal and polar mode number of the ell=m modes in the turbulent cascade.",
      "unit": "dimensionless",
      "domain_kind": "numeric_values",
      "minimum": null,
      "maximum": null,
      "allowed_values": [1, 2, 3, 4, 5],
      "domain_statement": "The nonlinear transfer timescales tau_pNL are restricted to modes with ell <= 5; the cascade spans ell=m modes up to ell_max=23.",
      "anchors": [
        {"line_start": 127, "line_end": 127, "support": "We restrict tau_pNL to modes with ell <= 5."},
        {"line_start": 101, "line_end": 101, "support": "Include modes with ell=m>=0 up to ell_max=23."}
      ]
    }
  ],
  "readouts": [
    {
      "name": "tau_pNL",
      "definition": "Nonlinear energy transfer time for potential-type self-interactions, defined as the coordinate time between the peak of -<E_ell> and -<E_{ell+1}> in the range separating the first and second instability saturation.",
      "unit": "M",
      "statistic": "Time between peaks of rolling time-averaged linear energies; values are read from Fig. 3, not numerically tabulated.",
      "uncertainty": "source_unspecified",
      "resolution": null,
      "anchors": [
        {"line_start": 127, "line_end": 127, "support": "Define nonlinear timescale tau_NL_l as coordinate time between peak of -<E_l> and -<E_{l+1}>; for potential-type self-interactions, tau_pNL."}
      ]
    },
    {
      "name": "tau_dNL",
      "definition": "Nonlinear energy transfer time for derivative self-interactions, defined analogously to tau_pNL.",
      "unit": "M",
      "statistic": "Time between peaks of rolling time-averaged linear energies; values are read from Fig. 3, not numerically tabulated.",
      "uncertainty": "source_unspecified",
      "resolution": null,
      "anchors": [
        {"line_start": 127, "line_end": 127, "support": "Derivative self-interactions induce efficient energy transfer with roughly constant nonlinear transfer time tau_dNL."}
      ]
    },
    {
      "name": "E_ell",
      "definition": "Linear energy of the ell=m mode, with negative values for unstable modes except E_00 positive.",
      "unit": "M",
      "statistic": "Rolling time-average <E_ell>; energies are negative except E_00.",
      "uncertainty": "source_unspecified",
      "resolution": null,
      "anchors": [
        {"line_start": 105, "line_end": 105, "support": "Evolution of energies E_ell for ell>=0; <...> indicates rolling time-average; all shown energies are negative except E_00>0."}
      ]
    }
  ],
  "claims": [
    {
      "claim_id": "linear_e_folding_time_m1",
      "statement": "The energy e-folding time of the ell=m=1 ergoregion unstable mode is tau_EI_1 = 1.2e4 M.",
      "quantitative_form": "tau_EI_1 = 1.2e4 M",
      "oracle_outputs": {
        "tau_EI_1": {"param": "tau_EI_1_value"}
      },
      "mechanism_ids": ["ergoregion_instability_linear"],
      "control_names": [],
      "control_domains": [],
      "readout_names": ["tau_EI_1"],
      "fixed_condition_ids": ["boson_star_background"],
      "applicability": "Valid on the specific spinning boson star background with the given parameters.",
      "statistical_basis": "Single value from frequency-domain methods in Ref. [Siemonsen:2025wib].",
      "uncertainty": "source_unspecified",
      "depends_on": [],
      "anchors": [
        {"line_start": 101, "line_end": 101, "support": "On this background, the energy's e-folding time is tau_EI_{m=1}=1.2e4 M."}
      ]
    },
    {
      "claim_id": "monopole_decay_rate",
      "statement": "The energy decay rate of the ell=m=0 mode is approximately -4e-3/M, which is much larger than the growth rates of the ell=m>=1 unstable modes.",
      "quantitative_form": "decay_rate_E00 = -4e-3 / M",
      "oracle_outputs": {
        "decay_rate_E00": {"param": "monopole_decay_rate"}
      },
      "mechanism_ids": ["parametric_driving_monopole"],
      "control_names": [],
      "control_domains": [],
      "readout_names": ["decay_rate_E00"],
      "fixed_condition_ids": ["potential_type_only", "two_mode_initial_data"],
      "applicability": "Observed in the potential-type self-interaction case during the nonlinear saturation.",
      "statistical_basis": "Single reported value from numerical evolution.",
      "uncertainty": "source_unspecified",
      "depends_on": [],
      "anchors": [
        {"line_start": 111, "line_end": 111, "support": "We find the energy decay rate of this monopolar mode to be approx -4e-3/M."}
      ]
    },
    {
      "claim_id": "turbulent_cascade_qualitative",
      "statement": "The nonlinear saturation of the ergoregion instability triggers a weakly turbulent direct cascade that transfers energy from low-ell modes to high-ell modes, with nonlinear transfer timescales much shorter than the linear e-folding timescales.",
      "quantitative_form": "tau_NL_l << tau_EI_l for triggered cascade",
      "oracle_outputs": {
        "tau_pNL": {"var": "ell"},
        "tau_dNL": {"var": "ell"}
      },
      "mechanism_ids": ["turbulent_direct_cascade"],
      "control_names": ["ell"],
      "control_domains": [
        {
          "control_name": "ell",
          "domain_kind": "numeric_values",
          "minimum": null,
          "maximum": null,
          "allowed_values": [1, 2, 3, 4, 5],
          "domain_statement": "The nonlinear transfer timescales tau_pNL are restricted to modes with ell <= 5; the cascade spans ell=m modes up to ell_max=23.",
          "anchors": [
            {"line_start": 127, "line_end": 127, "support": "We restrict tau_pNL to modes with ell <= 5."}
          ]
        }
      ],
      "readout_names": ["tau_pNL", "tau_dNL"],
      "fixed_condition_ids": ["potential_type_only", "derivative_type_only", "two_mode_initial_data", "mode_truncation_ellmax_23"],
      "applicability": "Valid during the nonlinear saturation phase, for ell=m modes up to ell_max=23, and for both potential-type and derivative self-interactions.",
      "statistical_basis": "Qualitative observation from numerical evolutions; timescales are amplitude-dependent and independent of initial amplitude ratio.",
      "uncertainty": "source_unspecified",
      "depends_on": [],
      "anchors": [
        {"line_start": 119, "line_end": 119, "support": "Subsequent evolution characterized by weakly turbulent direct cascade from ell=m=1 towards large ell=m>1 modes."},
        {"line_start": 127, "line_end": 127, "support": "Once turbulent cascade is triggered, it dominates dynamics with timescales far shorter than e-folding times of any ell=m>1 modes."}
      ]
    },
    {
      "claim_id": "spectrum_stationarity",
      "statement": "Assuming constant energy injection into the ell=m=1 mode and stationarity of the spectrum, the energy spectrum satisfies E_ell ~ tau_NL_ell. For potential-type interactions, tau_pNL increases with ell, leading to a growing spectrum; for derivative interactions, tau_dNL is constant, leading to a decaying spectrum.",
      "quantitative_form": "E_ell ~ tau_NL_ell (stationary spectrum)",
      "oracle_outputs": {
        "E_ell": {"var": "ell"}
      },
      "mechanism_ids": ["turbulent_direct_cascade"],
      "control_names": ["ell"],
      "control_domains": [
        {
          "control_name": "ell",
          "domain_kind": "numeric_values",
          "minimum": null,
          "maximum": null,
          "allowed_values": [1, 2, 3, 4, 5],
          "domain_statement": "The nonlinear transfer timescales tau_pNL are restricted to modes with ell <= 5; the cascade spans ell=m modes up to ell_max=23.",
          "anchors": [
            {"line_start": 127, "line_end": 127, "support": "We restrict tau_pNL to modes with ell <= 5."}
          ]
        }
      ],
      "readout_names": ["E_ell"],
      "fixed_condition_ids": ["potential_type_only", "derivative_type_only"],
      "applicability": "Speculative late-time model, assuming constant energy injection and stationarity; valid for a range of mode numbers up to dissipation scale.",
      "statistical_basis": "Theoretical model based on rate equations; not directly measured.",
      "uncertainty": "source_unspecified",
      "depends_on": ["turbulent_cascade_qualitative"],
      "anchors": [
        {"line_start": 137, "line_end": 137, "support": "Model equations dot E_{l+1,l+1}=E_ll/tau_NL_l - E_{l+1,l+1}/tau_NL_{l+1}; stationarity implies E_ll ~ tau_NL_l."}
      ]
    }
  ],
  "source_ambiguities": [
    {
      "ambiguity_id": "tau_NL_values_not_tabulated",
      "statement": "The nonlinear transfer timescales tau_pNL and tau_dNL are shown in Fig. 3 but not numerically tabulated in the text, so their exact values are not available from the source packet.",
      "claim_ids": ["turbulent_cascade_qualitative", "spectrum_stationarity"],
      "mechanism_ids": ["turbulent_direct_cascade"],
      "control_names": ["ell"],
      "readout_names": ["tau_pNL", "tau_dNL"],
      "fixed_condition_ids": [],
      "anchors": [
        {"line_start": 127, "line_end": 127, "support": "Figure 3 compares nonlinear transfer times to linear e-folding timescales, but no numeric values are given in the text."}
      ]
    }
  ]
}
